"""Read-only independent receipt/output aggregation; no model inference/optimizer."""
import json,hashlib,pathlib,math
import numpy as np
R=pathlib.Path('/home/minjae/Documents/github/pallet-pose-handoff-20261006')
D=R/'_docs/experiments/pallet_joint_action_handoff_20261006_v1'
C=pathlib.Path('/tmp/pallet-joint-action-cache')
checks=[]
def read(p):return json.loads(p.read_text())
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def ck(name,ok,detail=None):checks.append(dict(check=name,pass_=bool(ok),detail=detail))
def close(a,b):return np.allclose(a,b,atol=1e-12,rtol=1e-10,equal_nan=True)
P=read(D/'A_protocol.json');manifest=read(D/'results/A_ID_MANIFEST.json')
fits=[read(p) for p in sorted((D/'A_fits').glob('*.json'))]
smoke=[read(p) for p in sorted((D/'A_smoke').glob('*.json'))]
ck('six_fit_complete',len(fits)==6 and all(f['complete'] and f['updates']==6000 and f['exposures']==96000 and not f['smoke'] and f['real_training']==0 for f in fits),dict(fits=len(fits),updates=sum(f['updates'] for f in fits),exposures=sum(f['exposures'] for f in fits)))
ck('four_smoke_updates_separate',len(smoke)==2 and sum(f['updates'] for f in smoke)==4 and all(f['smoke'] for f in smoke),dict(receipts=len(smoke),updates=sum(f['updates'] for f in smoke)))
for seed in [1,2,3]:
 f=[v for v in fits if v['seed']==seed]
 if len(f)==2:
  ck(f'seed{seed}_paired_order_and_initial_state',f[0]['order_sha256']==f[1]['order_sha256'] and f[0]['first_step']['initial_state_sha256']==f[1]['first_step']['initial_state_sha256'],{v['arm']:dict(order=v['order_sha256'],initial=v['first_step']['initial_state_sha256']) for v in f})
for f in fits+smoke:
 path=pathlib.Path(f['checkpoint_path']);ck(f"{f['arm']}_seed{f['seed']}_{'smoke' if f['smoke'] else 'fit'}_checkpoint_hash",sha(path)==f['checkpoint_sha256'])
 ck(f"{f['arm']}_seed{f['seed']}_first_step_feature_gradients",all(math.isfinite(f['first_step']['gradients'][k]) and f['first_step']['gradients'][k]>0 for k in ['adapt3.0.weight','adapt4.0.weight']))
g=read(C/'GENERATION_CODE_BINDINGS.json');ck('generation_code_guards_current',all(sha(R/k)==v for k,v in g['code_bindings'].items()))
for split,identity in [('SYNTH_HELDOUT','synthetic_evaluation'),('REAL_DEV','real_evaluation')]:
 base=read(D/f'results/A_{split}_BASELINES.json');methods={k:v for k,v in base['rows'].items()};summary=base['summary'];expected=manifest['IDs'][identity]
 for p in sorted((D/'results').glob(f'A_{split}_*seed*.json')):
  x=read(p);prefix='FIT' if x['trained'] else 'FROZEN';seed=int(p.stem[-1]);ck(p.name+'_denominator',x['full_denominator']==len(expected) and x['GT_inference_access'] is False)
  for key,rows in x['rows'].items():methods[f'{prefix}_{key}_seed{seed}']=rows;summary[f'{prefix}_{key}_seed{seed}']=x['summary'][key]
 ck(split+'_all_methods_full_locked_order',all([r['id'] for r in rows]==expected for rows in methods.values()),dict(methods=len(methods),frames=len(expected)))
 for name,rows in methods.items():
  vals=[r['corner']['E_sym'] for r in rows if r['corner']['evaluable']];ps=[r['pose'] for r in rows if r['pose']['available']]
  ck(split+'_'+name+'_summary',close(np.mean(vals),summary[name]['corner']['E_sym']) and len(ps)==summary[name]['pose']['available'] and summary[name]['pose']['total_frames']==len(expected))
  noop=sum(r['selected_index']==0 or isinstance(r['selected_index'],list) and all(v==0 for v in r['selected_index']) for r in rows);ck(split+'_'+name+'_NoOp_selection_summary',noop==summary[name]['NoOp'],dict(actual=noop,reported=summary[name]['NoOp']))
 gap=read(D/f'results/A_{split}_ORACLE_GAPS.json');oracle=read(D/f'results/A_{split}_ORACLE.json');lookup={(r['id'],r['arm']):r for r in oracle['rows']}
 ck(split+'_two_banks_full_oracle_ids',all([r['id'] for r in oracle['rows'] if r['arm']==arm]==expected for arm in ['GEO','PERM']))
 for name,rows in gap['rows'].items():
  source=methods[name];arm=name.split('_')[1];ok=[r['id'] for r in rows]==expected
  for r,s in zip(rows,source):
   o=lookup[(r['id'],arm)];delta=s['pose']['ADDsym_m']-o['oracle_ADDsym_m'] if s['pose']['available'] and o['oracle_ADDsym_m'] is not None else None
   ok &= (delta is None and r['ADDsym_gap_m'] is None) or (delta is not None and close(delta,r['ADDsym_gap_m']))
  gs=gap['summary'][name];ck(split+'_'+name+'_same_bank_oracle_gap',ok and (gs['negative_beyond_numeric_tolerance']==0 if '_J_' in name else True),dict(common_success=gs['common_success'],frames=gs['total_frames']))
 comp=read(D/f'results/A_{split}_COMPARISONS.json')
 ck(split+'_three_controlled_contrasts_present',all(k in comp for k in ['FIT_GEO_J_minus_FIT_PERM_J','FROZEN_GEO_J_minus_FROZEN_GEO_I','FROZEN_PERM_J_minus_FROZEN_PERM_I']))
 for key,v in comp.items():
  name,ref=key.split('_minus_');arr=[];bas=[];samepose=np.ones(len(expected),bool)
  for ss in [1,2,3]:
   a=methods[f'{name}_seed{ss}'];b=methods[ref if ref=='RAW' else f'{ref}_seed{ss}'];arr.append([r['corner']['E_sym'] if r['corner']['evaluable'] else np.nan for r in a]);bas.append([r['corner']['E_sym'] if r['corner']['evaluable'] else np.nan for r in b]);samepose&=np.array([r['pose']['available'] for r in a]) & np.array([r['pose']['available'] for r in b])
   coverage=v['per_seed'][ss-1]['pose_paired'];quad=[sum(x['pose']['available'] and y['pose']['available'] for x,y in zip(a,b)),sum(x['pose']['available'] and not y['pose']['available'] for x,y in zip(a,b)),sum(y['pose']['available'] and not x['pose']['available'] for x,y in zip(a,b)),sum(not x['pose']['available'] and not y['pose']['available'] for x,y in zip(a,b))]
   ck(split+'_'+key+f'_seed{ss}_full_failure_quadrants',quad==[coverage[k] for k in ['common_success','new_only_success','base_only_success','both_failed']] and sum(quad)==len(expected))
  aa=np.array(arr);bb=np.array(bas);valid=np.isfinite(aa).all(0)&np.isfinite(bb).all(0);d=(aa-bb)[:,valid].mean(0);primary=v['E_sym'];ck(split+'_'+key+'_seedmean_delta',close(d.mean(),primary['delta']) and close((aa-bb)[:,valid].mean(1),primary['per_seed_delta']))
  if split=='REAL_DEV':
   sessions=np.array([r['session'] for r in methods[f'{name}_seed3']]);n=np.unique(sessions).size;ck(key+'_real13sessions',n==13)
   def bootstrap_diff(diff,groups):
    ids,inverse=np.unique(groups,return_inverse=True);n=len(ids);tot=np.bincount(inverse,weights=diff,minlength=n);count=np.bincount(inverse,minlength=n);rng=np.random.default_rng(20260917);samples=[]
    for _ in range(100):
     w=rng.multinomial(n,np.full(n,1/n),size=100);samples.extend(((w@tot)/(w@count)).tolist())
    return np.quantile(samples,[.025,.975]),n
   ci,units=bootstrap_diff(d,sessions[valid]);ck(key+'_independent_real_shared_session_CI',close(ci,primary['CI95']) and units==primary['units'] and primary['resamples']==10000 and primary['seed']==20260917)
   for metric,vv in v['pose_seed_mean_paired'].items():
    dd=np.array([[a['pose'][metric]-b['pose'][metric] for i,(a,b) in enumerate(zip(methods[f'{name}_seed{ss}'],methods[ref if ref=='RAW' else f'{ref}_seed{ss}'])) if samepose[i]] for ss in [1,2,3]]);ci,n=bootstrap_diff(dd.mean(0),sessions[samepose]);ck(key+'_'+metric+'_independent_real_session_CI',close(ci,vv['CI95']) and close(dd.mean(),vv['delta']) and int(samepose.sum())==vv['common_success_all3seed_frames'] and n==vv['units'])
 del base,methods,summary,gap,oracle,lookup,comp
out=dict(schema='pallet_independent_A_output_checks_v1',checks=checks,passed=sum(r['pass_'] for r in checks),failed=[r for r in checks if not r['pass_']],model_inference_calls=0,optimizer_updates=0,scope='Read-only receipt, output coverage, sums, gap and real whole-session seed-mean bootstrap reaggregation; reused QA probes are separate')
path=pathlib.Path('/tmp/pallet-independent-A-output-checks.json');path.write_text(json.dumps(out,ensure_ascii=False,indent=2,allow_nan=False)+'\n');print(json.dumps(dict(checks=len(checks),passed=out['passed'],failed=out['failed']),ensure_ascii=False))
